package com.slotix.reservationcore.availability;
import org.springframework.format.annotation.DateTimeFormat; import org.springframework.security.access.prepost.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/v1/companies/{companyId}/resources/{resourceId}/availability") public class AvailabilityController { final AvailabilityService service; public AvailabilityController(AvailabilityService s){service=s;} @GetMapping @PreAuthorize("hasAnyRole('COMPANY_ADMIN','BOOKING_MANAGER','CUSTOMER')") List<AvailabilitySlot> slots(@PathVariable UUID companyId,@PathVariable UUID resourceId,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate date,@RequestParam int durationMinutes){return service.slots(companyId,resourceId,date,durationMinutes);} }
